# When set, a value update is in progress. Maps each ComputeCell whose value
# changed during the update to its value before the update started. Callbacks
# are deferred until the update reaches a stable state so that a cell whose
# value ends up unchanged (or unchanged relative to the previous stable state)
# does not fire its callbacks.
_propagation = None


class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._observers = []

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        global _propagation
        self._value = new_value
        if _propagation is None:
            _propagation = {}
        try:
            for observer in list(self._observers):
                observer()
        finally:
            changed = _propagation
            _propagation = None
            for cell, old_value in changed.items():
                if cell._value != old_value:
                    for callback in list(cell._callbacks):
                        callback(cell._value)

    def add_observer(self, observer):
        self._observers.append(observer)


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self._inputs = inputs
        self._compute_function = compute_function
        self._observers = []
        self._callbacks = []
        self._value = self._compute_function(
            [input_cell.value for input_cell in inputs]
        )
        for input_cell in inputs:
            input_cell.add_observer(self._recompute)

    @property
    def value(self):
        return self._value

    def _recompute(self):
        old_value = self._value
        new_value = self._compute_function(
            [input_cell.value for input_cell in self._inputs]
        )
        if new_value != old_value:
            self._value = new_value
            if _propagation is None:
                self._fire_callbacks()
            else:
                # Record the value from before the update started so that
                # callbacks only fire if the stable value actually changed.
                _propagation.setdefault(self, old_value)
            for observer in list(self._observers):
                observer()

    def _fire_callbacks(self):
        for callback in list(self._callbacks):
            callback(self._value)

    def add_observer(self, observer):
        self._observers.append(observer)

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
